ProjectALife.DialogueShards["radio_12"] = {
{"exp_silence_roll","silence",14,3650,23,5,1,{"June","We don't need to fill every second tonight","June","If you're only listening, you don't have to introduce yourself","June","If you're trying to rest, there isn't a quiz at the end of this broadcast","June","You can miss a few words without missing an instruction","June","I haven't got an instruction for you","June","Just a little company, for however long the signal reaches","June","I'm going to put the microphone down now","June","Leave some quiet for whoever needs it more than another sentence"}},
{"exp_fence_receipts","caller_joke",14,3650,0,23,1,{"Harlan","I bought and sold things, nothing worth discussing in detail","June","Then let's keep the details to ourselves","Harlan","People always wanted a receipt when they bought something questionable","June","Did you give them one?","Harlan","Beautiful receipts - very official, carbon paper and everything","June","And the receipts made them feel better?","Harlan","Some folks trust bad news more if it's got a serial number","June","You make a worrying point remarkably well"}},
{"exp_deserter_bootname","caller_story_sad",14,3650,0,23,1,{"Caller","I'm not using my name - please don't ask for it","June","No name needed - what's on your mind?","Caller","I left people I was supposed to stay with","June","I can't judge what happened from here","Caller","I rehearsed an explanation for days - don't want to give it anymore","June","You can leave it there if that's enough","Caller","My name's still written inside my boots, funny thing to feel ashamed of","June","You don't have to read it out to us"}},
{"exp_gang_nickname","caller_story_sad",14,3650,0,23,1,{"Tiny","They call me Tiny, I'm not telling you why","June","Wasn't about to ask you to measure anything","Tiny","My grandmother was the only one who used my proper name","June","Did you mind when she did?","Tiny","Acted like I did, especially around my friends","June","And now?","Tiny","Now everybody calls me Tiny and it sounds like they mean someone else","June","We can leave the other name just between you and her"}},
{"exp_barge_lunch","caller_story_sad",14,3650,0,23,1,{"Del","A deckhand I knew ate the same lunch every shift","June","Never got tired of it?","Del","Said it gave him one less decision, bologna, mustard, white bread","June","That's a workable philosophy","Del","I used to bring elaborate sandwiches just to irritate him","Del","He'd inspect mine and say I'd brought too much thinking","June","Which one of you was right?","Del","These days I'd gladly eat his decision"}},
{"exp_salvage_argument","caller_joke",14,3650,0,23,1,{"Mack","Roy says every bent nail is still useful","Roy","Didn't say every nail, said that one","Mack","You say that about each one separately","Roy","That's called making an assessment","Mack","We've spent longer discussing this nail than a carpenter spent making the porch","Roy","Then quit interrupting the assessment","Mack","June, settle an argument - is a bent nail worth an afternoon?","June","Apparently it's worth an entire broadcast"}},
{"exp_barber_mirror","caller_story_sad",14,3650,0,23,1,{"Lou","Barbering was mostly getting people to sit still and talk","June","Any particularly good stories?","Lou","Some excellent lies about fish, I could tell the size of a fish by how late a man was to work","June","Bigger fish, later arrival?","Lou","Exactly, needed a story worth the trouble","Lou","I miss having that big mirror, could see the whole room without turning","June","That sounds useful in more than a barbershop","Lou","Used to look for regular customers, different things to watch for now"}},
{"more_radio_bad_singing_vote","caller_joke",14,3650,0,23,1,{"Pete","We held a vote about Lyle's singing","June","What was the result?","Pete","Six against - one abstained","June","Lyle?","Pete","Lyle voted against too, says he can't help it","Lyle","Song gets stuck in my head","Lyle","I don't notice I'm doing it till Pete starts throwing things","Pete","A sock, I threw ONE sock","Pete","We're considering separate sleeping arrangements","Lyle","Fine by me, he hums in his sleep and nobody believes me"}},
{"more_radio_nobody_said_thanks","caller_story_sad",14,3650,0,23,1,{"Jean","I got angry because nobody thanked me","Jean","Then I felt awful because they were tired and frightened","June","So were you","Jean","That's what somebody else said","Jean","I said I was fine, then I went round the back and cried - so, no, not fine","June","Oh, Jean, I'm sorry","Jean","I don't need a medal, I need someone to notice the bucket doesn't fill itself","Jean","And then offer to fill it, I don't want a speech - pick up the bucket","June","Have you told them that?","Jean","Not like that, mostly I've been banging it down where they can hear - yeah, I should tell them"}},
{"more_radio_cards_new_rules","caller_joke",14,3650,0,23,1,{"Lou","We're playing cards with five cards missing","June","What game?","Lou","Depends who's losing","Bess","He changes the rules every hand","Lou","Five cards missing, Bess, I have to change SOMETHING","Bess","Yesterday an eight beat everything","June","Did Lou have an eight?","Bess","June, please","Lou","This is why I don't invite the press","Bess","Next time we play, we're checking his pockets first"}},
{"more_radio_learning_rest","host",14,3650,18,23,1,{"June","I nearly signed off by telling everybody to get a good night's sleep","June","Then I remembered half of you are listening on watch - sorry - habit","Earl","Somebody's got to stay awake","June","I know, I didn't mean to forget them","Earl","I take it in pieces - sleep, get up, sleep again","June","Does somebody wake you when it's your turn?","Earl","Too gently, like they're sorry I have a job","June","Maybe they're sorry you're tired","Earl","Could be, I should stop snapping at them","Earl","I'll tell them when they wake me, if I can remember before I start swearing"}},
{"more_radio_showing_up_again","sign_off",14,3650,21,5,1,{"June","We're closing this part of the program","June","I had something written down for this - hang on... no, that's yesterday's","June","Never mind, thanks for the calls, I needed a laugh tonight, and a few of you gave me one","June","And to the lady who couldn't finish her story, you can call back - whenever you're ready","Lou","You taking the pencil count with you?","June","You can have the pencils - all four - or seven, whatever it was","Lou","Coward","June","Yes, a coward going to bed - move over, I need to reach the switch","June","Goodnight, everybody - and, uh... thanks for staying up with me","June","Knox County Radio, we'll speak again when we can"}},
{"more_radio_canning_labels","caller_joke",14,3650,0,23,1,{"Dot","My sister labels everything 'miscellaneous'","June","What sort of things?","Dot","Jars - boxes, a whole cupboard","June","At least you know what's in the cupboard","Dot","Miscellaneous","June","Exactly","Dot","We opened a jar yesterday - peaches","Dot","Perfectly ordinary peaches, you'd think that settled it","Dot","She wrote 'miscellaneous peaches' on it","June","Oh, for-- Dot, hide the pencil"}},
{"more_radio_old_key_ring","caller_story_sad",14,3650,0,23,1,{"Carl","I've got keys to things I haven't seen in weeks","June","You still carry them?","Carl","Everywhere, one's to a cabinet at work","June","Anything important inside?","Carl","Paper, a stapler nobody liked","Carl","You had to slam it or the lock wouldn't catch - should've got rid of it years ago","Carl","Still know which key it is without looking - this little... yeah, this one","June","Got them in your hand?","Carl","My son says the noise gives us away","June","Wrap them in something, then, you don't have to throw them away tonight"}},
{"more_radio_daughter_humming","caller_story_sad",14,3650,0,23,1,{"Ruth","My daughter was humming while she worked today","June","Something you recognized?","Ruth","A commercial - for carpet","Ruth","The awful one - don't worry, I'm not singing it","Ruth","I used to ask her to stop, drove me half mad","June","Not today?","Ruth","Today I found things to do in the same room","June","Did she notice?","Ruth","Told me I was folding the same towel twice","Ruth","I told her it wasn't straight, she knew I was lying"}},
{"more_radio_club_roll_call","caller_story_sad",14,3650,0,23,1,{"Red","We used to do roll call like it was a joke","Red","Nobody answered their own name - Fuckin' toilet got its own chapter somehow","Red","Secretary kept a spare pencil, he'd snap the first one, get so mad","Duke","You broke the pencils","Red","I broke ONE, all right, two - Christ, Duke","Red","Now we get through it pretty quick","Duke","You still read all the names","Red","I'm aware","Duke","Not asking you to stop","Red","Good, I'm not crossing them out - not yet"}},
{"more_radio_deserter_button","caller_story_sad",14,3650,0,23,1,{"Unknown Soldier","I took the name off my shirt","Unknown Soldier","The name tape, I mean, had to pick the stitching out","Unknown Soldier","My mother sewed one back on while I was home","Unknown Soldier","Used the wrong thread, I remember giving her shit about it","Unknown Soldier","She said nobody would look close enough to mind","Unknown Soldier","Name's gone now, but that one bit of thread... I keep looking at it","Unknown Soldier","I don't want anyone finding me from this call","June","You haven't told us a place","Unknown Soldier","Good, that's good","Unknown Soldier","Sorry, Mom, that's all, if she's-- if you're listening - I'm sorry"}},
{"more_radio_club_breakfast","caller_story_sad",14,3650,0,23,1,{"Duke","Biggest bastard I knew always cooked breakfast","Duke","You'd hear him swearing at the stove before anybody got up","Duke","He'd threaten to leave you hungry if you complained","Duke","Then he'd remember exactly how you liked your eggs","Red","Mine were always wrong","Duke","Yeah, on purpose, you sent them back once and he never forgot it","Red","Didn't work","Duke","Nothing did","Red","I'd eat those eggs now","Duke","Yeah, so would I"}},
{"more_radio_rough_apology","host",14,3650,0,23,1,{"Unknown","I told a kid to get lost this morning","Unknown","He asked a question, that's all he did","June","Can you tell him you're sorry?","Unknown","He's gone, I didn't ask where","Unknown","I've been walking around telling myself it's a hard world","June","It is","Unknown","Yeah, well, it didn't make me say that - I did","Unknown","Didn't even hear him out, he might've just wanted directions","Unknown","I keep looking for him, like he's going to come back just so I can feel better","June","I hope you do see him again, I don't know what else to say - I'm sorry"}},
{"king_radio_borrowed_name","caller_story_sad",14,3650,0,23,1,{"Tess","I used a different name when I met some people","June","Did you feel safer?","Tess","For a minute. Now I want to tell them the real one","June","What makes it difficult?","Tess","They've been kind. Makes the lie feel worse","June","You can tell them why you were frightened","Tess","I suppose I have to let them decide what they think","June","Yeah. I think you do"}},
{"king_radio_handshake","caller_story_sad",14,3650,0,23,1,{"Wayne","Met a fellow who put his hand out before he said anything","June","Did you shake it?","Wayne","Took me a second. Then I felt rude about taking a second","June","Did he mind?","Wayne","Didn't seem to. Said his name was Perry","June","Have you seen him since?","Wayne","No. Thought if he's listening, I'd say it was good to meet him","June","Perry, if you're listening, Wayne remembers"}},
{"knox_boot_laces","military",14,3650,0,23,1,{"Corporal","Used to judge a man on whether his boots were polished","Private","What do you judge him on now?","Corporal","Whether he tells you when your laces are loose","Private","Yours are loose, Corporal"}},
{"knox_breakfast_memory","caller_story_sad",14,3650,0,23,1,{"Doris","My husband always burned the first piece of toast, every morning, forty-one years","June","Did he ever blame the toaster?","Doris","Every morning, forty-one years","Doris","I'd give anything to hear him lying about that toaster again"}},
{"knox_doorbell_joke","caller_joke",14,3650,0,23,1,{"Cal","I miss door-to-door salesmen","June","That's a fairly unusual thing to miss","Cal","At least you knew what they wanted, usually a ridiculous amount for a vacuum","June","I'll put vacuum salesmen down as cautiously missed"}},
{"knox_unnamed_kindness","caller_story_sad",14,3650,0,23,1,{"Earl","Years ago, a woman paid for my gas when my card wouldn't work - never got her name","June","What made you think of her?","Earl","Nothing special, I just wanted to remember somebody doing something kind without asking first","June","That's a good reason to call"}},
{"r2_d14_nomad_water_plant","military",14,15,1,6,2,{"Nomad 1-1","Warden Tac, Nomad 1-1, passing through your line at TCP 3 eastbound, two vehicles - do not challenge, authentication Sierra Tango, over","Warden Tac","Nomad 1-1, Warden Tac, I have no traffic on you - say your mission, over","Nomad 1-1","Negative - authentication stands, your checkpoint will see two civilian pickups, lights off, over","Warden Tac","Wait one, authentication is valid - TCP 3 will pass you - do you require anything, over?","Nomad 1-1","Negative - be advised, the Riverside water plant is clear as of 0300 - nine of your people were there, tags recovered, over","Warden Tac","Say again, nine, over?","Nomad 1-1","Nine, tags will be left at TCP 3 - Nomad 1-1, out","Warden Tac","Hammer-3-7, Warden Tac - are you on this net, over?","Hammer-3-7","Hammer-3-7, I heard it, over"}},
{"r3_host_d14_short_list","host",14,22,0,23,1,{"Marty","Two weeks on the air, I thought I'd go over what we know now that we didn't know on the first day - it's a short list, so don't get up","Marty","Don't trust a fence to hold forever. Keep another way out in mind","Marty","A shot to the head ends them, a shot anywhere else just aggravates them and tells every other one within a mile where you're standing","Marty","They follow each other, one starts walking, twenty fall in behind it, and not one of them knows where they're going","Marty","And the Army isn't coming this week, that ain't a rumor, I've been counting two weeks now","Marty","That's the list, I'd hoped it would be longer - mostly I'd hoped that last one would be different"}},
{"r3_host_d14_eleven_bite_calls","host",14,30,9,20,1,{"Dee","If you've been calling on nineteen about a bite, listen a minute. Eleven calls so far. This answer's for all eleven","Dee","I don't have anything for a bite, nobody I know of does, not cutting it out, not burning it, not whiskey, not the tea the church lady in Ekron is handing out","Dee","I sat with two people on my hall who got bit - I did everything right for both of them, it didn't matter","Dee","If it's you, say what you need to say while you can. If it's somebody you love, sit with them. Have somebody else in the house too, somebody rested and ready","Dee","I'd rather tell you straight than have you spend the good day you've got left chasing something that isn't there","Dee","That's what I know. I'm sorry it isn't more. Get some water in you, alright?"}},
{"r3_ins_d14_hens","instruction",14,30,6,12,1,{"Marty","Some of you have laying hens, and you've been bringing me questions about them, which is the first question in three weeks I actually know the answer to","Marty","A laying hen eats about a quarter pound of feed a day - if you run out, let them out in the yard in daylight - they'll eat bugs and grass, and they'll lay less, but they'll lay","Marty","Crush the eggshells and put them back in the feed to keep the shells hard - bake them first, or your hens will get a taste for their own eggs","Marty","Shut them up well before dark, anything walking around at night is going to find a chicken house loud","Marty","And no roosters, I've learned that lesson on your behalf"}},
{"r3_mb_d14_leon_harmonica","music_bridge",14,30,18,22,1,{"Caller - Leon","Breaker one-nine, Marty, it's Leon, in the trailer by the rock quarry, you said you don't have any music - I've got a harmonica - can I?","Marty","Leon, keep it low and keep it short, and you've got the county","99.6 FM","(A harmonica, played soft and not very well, for about a minute - it gets through to the end)","Caller - Leon","That's the only one I know, I also know it faster, if anybody wants that","Marty","Maybe tomorrow, Leon - thank you"}},
{"r3_sil_d14_counting_sixty","silence",14,30,0,4,1,{"99.6 FM","(Static, under it, very faint, a woman counting to sixty, then starting over)","Dee","Sorry, taking a pulse - mine - it's fine - carry on"}},
{"r4_sad_paint_stirrers","caller_story_sad",14,30,16,21,1,{"Caller - Sam","I'm the caretaker at the churchyard in March Ridge, was, before, and I guess I still am","Caller - Sam","I've been making crosses out of lath from the lumber yard - ran out of lath Thursday","Caller - Sam","Found a box of paint stirring sticks at the hardware store - the free ones, with the store's name printed on them - two nails each","Caller - Sam","So the last few graves have got a hardware store's name on them - I turned the printing around to face down, I hope that's alright with folks","Marty","It's alright, Sam","Caller - Sam","Thirty-seven, that's the number now, thirty-seven since the ninth - I'm not calling for anything, I just don't want to be the only one that knows the number","Caller - Sam","I write names on them with a carpenter's pencil, the rain takes it off, I go back and write them again","Dee","(Dee doesn't speak)","Marty","Thirty-seven, we'll remember it"}},
{"r4_sad_bowling_shirts","caller_story_sad",14,30,19,23,1,{"Caller - Dewey","We had a Tuesday league team at the lanes in West Point - four of us - twelve years, never won a thing","Caller - Dewey","This spring we finally ordered team shirts - maroon, names stitched over the pocket - Dewey, Clint, Pete, Albert","Caller - Dewey","They came in at the embroidery shop on the eighth - I picked the box up that Thursday afternoon, paid the balance","Marty","Did you get to wear them?","Caller - Dewey","No - Tuesday was the thirteenth, nobody was bowling on the thirteenth","Caller - Dewey","I wear mine now, it's the only clean shirt I've got - I've got Albert's too - Albert's is an extra-large tall, that was Albert","Caller - Dewey","I haven't heard from Clint or Pete, I've got theirs folded in the box - I keep the lid on so it doesn't get dusty","Marty","(Marty doesn't answer right away)","Caller - Dewey","Clint, Pete, if you're out there, your shirts came in, they look real sharp"}},
{"r5_host_folks_tally","host",14,90,0,23,1,{"Dee","I started keeping a tally of how many times Marty says 'folks' in an hour","Marty","That's a poor use of a good pencil","Dee","Forty-one, last hour it was forty-one","Marty","Well, what would you have me call them?","Dee","I'm not asking you to stop, I'm telling you I'll know when you're coming down sick, because the number will drop","Marty","Forty-two, then, folks"}},
{"r5_host_red_wasp","host",14,80,0,23,1,{"Marty","If I go quiet for a minute, there's a red wasp loose in this storeroom, and one of us is leaving","Dee","He's holding a rolled-up seed catalog like a billy club","Marty","I have lived through the fall of Knox County, I will not be undone by a wasp","Dee","He swung, he hit the microphone - some of you heard that","Marty","The wasp has the storeroom, we'll be broadcasting from the loading dock for the rest of the hour"}},
{"r5_joke_wanda_recliner","caller_joke",14,120,17,22,1,{"Caller - Wanda","Marty, my husband's been gone two weeks on a supply run up toward West Point","Marty","I'm sorry, Wanda, that's a long time","Caller - Wanda","I'm worried sick, I pray on it every night, I check the road every hour","Caller - Wanda","And for the first time in twenty-six years of marriage, I have got the recliner","Marty","He's coming home, Wanda","Caller - Wanda","I know it, that's why I'm in it right now, Marty - got to get my minutes in"}},
{"r8_hor_mowed_in_stripes","caller_story_horror",14,180,22,4,2,{"Leland","This ain't mine, understand, fella that fixed our well told me, and he don't tell stories","June","All right","Leland","Yard on the Rosewood side, little yellow house - grass cut - cut proper, in stripes, the way a man does it when he cares","Leland","There ain't been gas to spare for a lawn in weeks - and nobody's lived in that house since the tenth","June","Could somebody be staying there?","Leland","House is open to the weather, birds in the kitchen - nobody's staying in it","Leland","But somebody mowed it, and then a week later he went by and somebody had mowed it again","Leland","That's as far as he'd tell it, I asked him the rest and he said ask somebody else"}},
{"r8_hor_marquee_counting_down","caller_story_horror",14,180,0,5,1,{"Reverend Hollis","Go ahead, friend, this is a slow hour and I've got nowhere to be","Ina","The marquee at Little Bethel, the one out front with the letters you slide in","Ina","It's got a number on it now, just a number, no words, it was eleven on Sunday","Reverend Hollis","And now?","Ina","Six, it goes down one a day, somebody's out there in the night with the letters","Reverend Hollis","I'd want to know who has the key to that case","Ina","Brother Stiles had the key and Brother Stiles is buried behind that church - I helped dig it","Reverend Hollis","Then I'll be at that marquee in the morning with two men and a light - not tonight","Ina","Not tonight - no, that's why I called at this hour, so you wouldn't go tonight"}},
{"r8_hor_splitting_wood_three_am","caller_story_horror",14,170,1,5,1,{"Ewell","Somebody's splitting wood at three in the morning up the holler","June","You can hear it clearly?","Ewell","Clear as a bell, maul on a wedge, then the crack - ring, ring, crack, steady as a clock","Ewell","An hour of it, and there's no light up there, not a lantern, not a fire, not a flashlight","June","A man wouldn't split wood in the dark","Ewell","You'd take your foot off, I split wood my whole life and I wouldn't swing a maul without light, not for money","June","Have you gone up in the daytime?","Ewell","There's a pile up there, split and stacked, good and square, cord and a half maybe - growing","Ewell","Somebody's putting up wood for winter and it's the middle of July - I couldn't tell you which part of that bothers me worse"}},
{"r8_hor_dry_in_the_rain","caller_story_horror",14,170,22,4,1,{"Sudie","It come a gullywasher Thursday evening, you was probably in it, everybody was in it","June","I was","Sudie","We walked in from the barn, four of us, soaked to the skin - and there was a man come up the lane at the same time, walking","Sudie","Dry","June","He could have been under something","Sudie","That lane's a quarter mile of open ground, not a tree, not a shed - we watched him the whole way up it in the rain","Sudie","Shirt dry - hair dry, shoes not even muddy, and that lane's clay","June","Did anybody say anything to him?","Sudie","My father in law said you must've found a porch to wait it out on - and the fella said yes sir, that was the whole conversation"}},
{"r8_hor_named_all_of_us","caller_story_horror",14,175,1,5,1,{"Thelma","There's a boy come up to our fence, ten, eleven years old - barefoot","June","By himself?","Thelma","By himself, and you know what that does to a person - everybody was at that fence inside a minute","Thelma","He named us - every one, nine people, first try, no misses","June","Somebody might have told him who lives there","Thelma","He pointed, he pointed at each one and said the name, he got my daughter in law, and she's been with us eleven days","June","Did you let him in?","Thelma","We did, course we did, he's a child, what kind of person do you think I am","Thelma","He's asleep in the front room right now, and I'm out here on the porch with a radio and I ain't going to sleep tonight"}},
{"r8_hor_time_under_the_chalk","caller_story_horror",14,175,1,5,1,{"Dwight","I chalk my handle on the rail of the Carver bridge when I go over - little thing I started, so folks know I'm still going","June","Leaving a mark","Dwight","A rabbit and the date - foolish, I know, just a piece of chalk","Dwight","Went over Sunday, somebody had wrote a time under it","June","A time","Dwight","Four twenty - that's it, four twenty, in chalk, right under Rabbit","June","Does that mean anything to you?","Dwight","It's about when I come across, I'd say inside ten minutes of it, both trips that week","Dwight","So somebody's got a watch and a piece of chalk and they know my crossing - I go over at night now, which is worse, and I know it's worse"}},
{"r8_hor_elevator_no_pigeons","caller_story_horror",14,180,0,4,1,{"Gilbert","Grain elevator out past Wickham's, the tall one, the concrete","June","I can see it from here in the daytime","Gilbert","Pigeons, hundreds of 'em, always, my whole life - they'd come off that thing in a sheet when a truck pulled in","Gilbert","There's not a bird on it","June","They could have moved on","Gilbert","Moved where? There's corn spilled all over that lot, there's a foot of corn in the pit - it's the best place in the county to be a pigeon","Gilbert","And there's no dead ones neither, I walked the whole apron looking for dead ones and there's nothing","June","So they left the food","Gilbert","A bird don't leave food, that's just how a bird is, so I've took to looking up when I go by, which is a habit I'd rather not have"}},
{"r8_hor_horses_and_the_guard","caller_story_horror",14,175,22,4,1,{"Reba","We've got two mares - old girls, been on this farm eleven years","June","Go ahead","Reba","There's a cattle guard between the two pastures, pipe one, set in concrete, they've walked over it twice a day for eleven years","Reba","They won't cross it now","June","Did something happen at it?","Reba","Not a thing, it's the same pipe, I've been out there on my knees looking for a broke weld or a snake or wasps, and there's nothing","Reba","They come up to it and stop and back off - both of 'em, my daughter tried to lead the little one across and she planted and would not come","June","So you go around","Reba","We cut the fence and made a gap forty foot down - they walk through that just fine","Reba","I don't go over the guard no more neither, I go down to the gap - my husband thinks that's the funniest thing he ever heard"}},
{"r8_hor_fires_answering","caller_story_horror",14,180,0,4,2,{"Glenda","We lit a fire Tuesday, first one in weeks, we'd been cold-camping, had a hog to cook","June","That's a lot of light","Glenda","We knew it, we done it anyhow, you can't smoke a hog in the dark","Glenda","Wednesday night there was one on the far ridge","June","One fire","Glenda","One, same size as ours, near as I could tell - Thursday there was three","June","Three","Glenda","Spread out along that ridge, even spaces between 'em, like fence posts","June","What did you do Friday?","Glenda","Didn't light one, and Friday there wasn't none on the ridge neither - so somebody's counting, and now they know we quit"}},
{"r8_sad_hem_still_pinned","caller_story_sad",14,175,20,2,1,{"Darlene","There's a dress hanging in my closet in a dry cleaner bag","June","A wedding dress?","Darlene","My mother made it, started it in February, she had me stand on a kitchen chair and she went around the bottom on her knees","June","Go on","Darlene","The hem's still pinned, she was going to sew it the week of, so it'd hang right - she didn't trust it sitting sewed all spring","Darlene","So there's about sixty of her pins in that hem - her pins, out of the tomato pincushion","June","And the wedding","Darlene","Mark's fine - Mark's right here, he's got the flashlight, it ain't about the wedding","Darlene","I can't take the pins out and I can't leave 'em in - that's the problem, and it's a stupid one to have","June","It isn't a stupid problem","Darlene","Her name was Ruby, I just want somebody else in this county to know there's a woman named Ruby put them pins in"}},
{"r8_sad_cooler_wrong_name","caller_story_sad",14,180,0,4,1,{"Dee","You're on with Dee - go ahead","Arvel","I've been carrying a lunch cooler that ain't mine for eleven days","Dee","Whose is it?","Arvel","Got a strip of tape on the lid with a name on it - Vernon, wrote in marker, the way you do at a plant so nobody takes your sandwich","Dee","Where did you get it?","Arvel","Grabbed it off a bench going out the door on the ninth - everybody grabbed something, I grabbed the wrong cooler and kept going","Arvel","There was a sandwich in it and an apple and one of them little thermos bottles - I ate the sandwich the first night","Dee","You were hungry","Arvel","I was, and there's a note in the bottom in a woman's hand about calling somebody about a tire","Arvel","So if there's a Vernon out there, I've got your cooler and your thermos and your note, and I'd like to hand it to you","Dee","We'll put that out again in the morning - Vernon, a cooler, a thermos and a note about a tire","Arvel","Tell him I'm sorry about the sandwich, he'd probably laugh at that, I don't know the man"}},
{"r9_joke_d14_undefeated_little_league","caller_joke",14,70,16,22,1,{"Caller - Elmo","Marty, I coached the eleven and twelves at the park in Muldraugh - I'm still holding practice Tuesdays and Thursdays","Marty","How many are coming out?","Caller - Elmo","Two, two boys and a bucket of balls, and one of them's my grandson and has to come","Marty","And how's the season going?","Caller - Elmo","We're nothing and nothing, nobody has beat us, I've told them that's the same as undefeated and I've told them to quit asking me questions about it","Caller - Elmo","We take infield, we run the bases, then we sit in the dugout and drink water and I tell them about the year we went to Bowling Green","Marty","Anybody out that way with a kid and a glove, that's Tuesday and Thursday at the park in Muldraugh","Caller - Elmo","Bring a glove or don't, I've got three gloves and no hands to put in them"}},
{"king_radio_old_swimming_hole","caller_story_sad",15,3650,0,23,1,{"Glenn","We used to tell the younger kids there were snakes in the swimming hole","June","Were there?","Glenn","Probably. We weren't brave enough to check, either","June","So nobody went swimming?","Glenn","Nobody that believed us","June","You feel bad about it?","Glenn","Little bit. Mostly I miss having something that stupid to be scared of","June","I can understand that"}},
{"r2_d15_tags_in_a_sock","military",15,20,6,18,1,{"Hammer-3-7","Warden Tac, Hammer-3-7, at TCP 3, I have the tags, over","Warden Tac","Roger - do you need to pass anything, over?","Hammer-3-7","Negative names, a count only - nine sets, all nine, over","Warden Tac","Roger, nine sets, over","Hammer-3-7","They were tied up in a sock, folded over twice and knotted, that wasn't the team that found them - one of mine did that, before, over","Warden Tac","Understood, Sergeant, over","Hammer-3-7","It's a green sock - Bybee wore green ones against regulation, I'm going to stop calling them on the hour now - hammer-3-7, out"}},
{"r3_sf_d15_pinned_watch","sign_off",15,30,0,2,1,{"Dee","It's two o'clock by the watch pinned on my shirt - I wore this watch every shift for eleven years, it's the only piece of the uniform I kept","Dee","I kept it because I still check it, every two hours I look down, and my feet want to go do rounds","Dee","So tonight my rounds are you, anybody on nineteen who wants a check, key up once - I'll key back - that's rounds","Dee","Okay, off the air, good night, hall"}},
{"r3_ins_d15_splint_as_it_lies","instruction",15,30,0,23,1,{"Dee","Broken bones, three calls this week - folks are climbing fences they shouldn't and jumping off porches they shouldn't - don't, but if you did","Dee","If you can't move it, or it's bent where there's no joint, treat it like it's broken - don't try to straighten it unless there's no pulse past the break","Dee","Splint it the way it's lying, something stiff on both sides, a yardstick, a paint stirrer, a rolled-up magazine - tie it above the joint and below the joint","Dee","Check the fingers or toes after, pink and warm is good - blue or cold, you tied it too tight - loosen it","Dee","Then keep still, I know you can't keep still - keep stiller"}},
{"r3_wx_d15_green_sky","weather",15,25,5,10,2,{"Marty","Weather, and this one matters, the barometer's falling faster than I've seen it all summer, and the sky to the west this morning is green along the bottom","Marty","A green sky in July, in this part of Kentucky, means hail and high wind, and sometimes worse than that","Marty","Nobody is going to sound a siren today, nobody's going to break into the program - I'm the program","Marty","So plan now - pick the lowest room in the house with no windows - put shoes, a flashlight, and a jug of water in it this morning while it's calm","Marty","If you see the clouds start to turn around each other, go to that room and stay till it's past - I'll be on the air as long as the antenna stands"}},
{"r3_mb_d15_dont_knob","music_bridge",15,30,0,23,1,{"Marty","Short break - Dolly walked across the desk a minute ago and set her foot square on Lloyd's knob - the one labeled 'DON'T'","Marty","Nothing happened, I've been staring at it - nothing happened at all","Dee","Maybe that's what it does, maybe Lloyd just didn't like it","Marty","That would be very Lloyd - stand by, folks, I'm going to go sit down"}},
{"r4_sad_marty_mother_calls","caller_story_sad",15,30,21,23,1,{"Dee","Marty's been working up to this all day - go on, Marty","Marty","My mother lives in a senior apartment in Louisville - eighty-four, I called her every Sunday at four - every Sunday, twenty-some years","Marty","She'd pick up and say, is this a salesman? Every single time - twenty years of that joke, she thought it was the best joke in Kentucky","Marty","Sunday the eleventh I didn't call her, I was on this microphone, I was doing this","Marty","I thought, she'd understand, she'd tell me to go help people - and by Monday the phones were gone","Marty","So every Sunday at four I pick up the dead phone in the store and I say, no, Mama, it's not a salesman","Marty","That's all - it's Sunday, it was just four o'clock","Dee","(Dee doesn't say a word, after a while she slides a cup of water across the desk, and he drinks it)"}},
{"r5_trade_insulin_shirley","trade",15,90,9,16,2,{"Dee","Trading Post, and this one came to me first, so I'm going to handle it - Shirley, go ahead","Caller - Shirley","I've got insulin, four vials and a box of syringes, it was my husband's, he won't need it","Dee","What does the label say, Shirley? Read it to me slow","Caller - Shirley","It says NPH, and the date on the side says March of ninety-four","Dee","Has it been kept cool?","Caller - Shirley","In the spring house since the power went, it's cold down there as a church","Dee","Whoever needs it, call me, not her, I'll set it up - Shirley, what do you want for it?","Caller - Shirley","Nothing, I don't want a thing - he'd have been ugly about it if I let it go to waste","Dee","Where will you be?","Caller - Shirley","The lot by the Muldraugh water tower, nine in the morning - I'll have it in a cooler","Dee","Wrap it in a wet towel inside the cooler - don't let ice sit right on the vials, thank you, Shirley"}},
{"r5_host_dee_night_chart","host",15,120,0,4,1,{"Dee","It's just me for a while - Marty's asleep on a stack of feed sacks, snoring like a tractor","Dee","Eleven years of nights, and I still look at the clock at two and write the time down - we did rounds on the two","Dee","I've been writing down everybody who calls in, first name, what's wrong, how they sounded, same as a chart","Dee","Nobody's ever going to read it, I know that - but you called, and I wrote you down, and I'd like to know how you're doing","Dee","So, the lady out past Ekron with the swollen ankle - if you've got batteries and a way to call, please do - I'd like to close your chart"}},
{"r5_obit_caller_gorman_bell_tower","obituary",15,90,8,20,1,{"Caller - Brenda","Mr. Hal Gorman, scoutmaster out of Riverside, I'd like him read, please","Marty","Go ahead, Brenda","Caller - Brenda","On the ninth he got six boys up in the bell tower at the Riverside church - then he went back down for the seventh","Caller - Brenda","The seventh was my son, they came up the ladder together, and Mr. Gorman pulled the ladder up after them","Caller - Brenda","He didn't come down with the boys in the morning - he told them he'd follow","Caller - Brenda","All seven of them double-knot their shoes now, he used to make them tie them twice at every meeting","Marty","Hal Gorman of Riverside, seven boys double-knot their shoes"}},
{"r5_trade_formula_tony_mavis","trade",15,120,9,16,1,{"Marty","Tony in Rosewood, go ahead","Caller - Tony","I need baby formula - any kind, my girl's four months, and we've been stretching the last can with extra water","Dee","Tony, stop stretching it, mix it exactly like the can says, even if it runs out sooner - watered-down formula can hurt her worse than you'd think","Caller - Tony","Yes ma'am, I've got a chainsaw that runs and a full five-gallon can of gas - either one","Marty","We've got somebody holding - go ahead, you're on","Caller - Mavis","This is Mavis, also Rosewood, I've got nine cans of powdered formula - my grandbaby's weaned, I don't want his chainsaw","Caller - Tony","Ma'am, you've got to take something","Caller - Mavis","Fine, half the gas, the Rosewood courthouse steps, eleven tomorrow - bring the baby, so I can see her","Marty","Everybody listening just heard a trade happen in under two minutes - Rosewood courthouse steps, eleven AM - bring the baby"}},
{"r5_joke_ernie_courthouse_shade","caller_joke",15,60,17,22,1,{"Caller - Ernie","It's so hot in Rosewood today, three of them are sitting in the shade of the courthouse, not moving a lick","Marty","They're not after you?","Caller - Ernie","They were, then they got to the shade, now I can't tell if they want me or my spot","Marty","Ernie, you stay out of that shade","Caller - Ernie","Marty, it's the only shade in Rosewood, it's going to come to a fight"}},
{"r5_trade_boyd_no_ammo","trade",15,150,9,16,1,{"Caller - Boyd","Marty, I've got a hundred rounds of thirty-aught-six, and I want coffee","Marty","Boyd, you know the rule, no guns and no ammunition on this station","Caller - Boyd","That's a fool rule, people need rounds a lot more than they need salt blocks","Marty","They do, and if I send somebody out to meet a stranger with a hundred rounds in his truck, I'm the one who has to sleep after","Dee","He barely sleeps as it is - don't make it worse, Boyd","Caller - Boyd","So I can't trade them","Marty","You can't trade them here, I will say this on the air, for no reason at all - Boyd has a truck, and Boyd wants coffee","Caller - Boyd","Well, that's something","Marty","That's nothing, I said nothing - next caller"}},
{"r5_obit_caller_deputy_pike_back_steps","obituary",15,120,8,21,1,{"Caller - Sheila","I'd like to say Deputy Norman Pike, of the Sheriff's office","Caller - Sheila","On the tenth he came up my road in his cruiser, telling everybody to lock their doors - I told him the lock on my back door was broke","Caller - Sheila","He sat down on my back steps and said, 'Then I'll be your lock, ma'am, till your brother gets here'","Caller - Sheila","Four hours, in that heat, hat over his face, and every time something moved in the corn, he'd stand up","Caller - Sheila","When my brother's truck came up the road, Deputy Pike tipped his hat and walked on to the next house","Marty","Deputy Norman Pike, we'll leave a little quiet here"}},
{"r5_obit_dee_doctor_car_keys","obituary",15,120,0,5,1,{"Dee","I've been putting this one off","Dee","Dr. Samuel Adeyemi, he came from Nigeria to Kentucky in nineteen seventy-nine, and he used to say the first thing he had to learn here was how to say 'y'all' right","Dee","On the eleventh, in the middle of all of it, he put his car keys in my hand and said, 'Deanna, go'","Dee","I thought he wanted his car moved, so I went out and moved it, parked it closer to the door for him","Dee","When I came back in, he wasn't at the desk anymore","Dee","I drove that car till it ran out of gas outside Muldraugh - I've still got the keys, he'd be embarrassed how dirty I let it get"}},
{"r5_joke_clem_bedsheet_bill","caller_joke",15,120,17,22,1,{"Caller - Clem","Marty, an Army helicopter came over my place so low it peeled the shingles off half my roof","Marty","I'm sorry, Clem","Caller - Clem","I want to know who to bill","Marty","I'd guess Uncle Sam, care of Fort Knox","Caller - Clem","That's what I did, painted it on a bedsheet and spread it on the roof - 'US Army owes Clem Tackett forty shingles'","Marty","Did they see it?","Caller - Clem","They came back around twice to read it, then they blew the bedsheet off too"}},
{"r5_joke_randy_voice_drops","caller_joke",15,200,17,22,1,{"Caller - Randy","I've got a medical question for the nurse","Dee","Go ahead, Randy","Caller - Randy","Is it normal for a grown man's voice to drop about an octave every time a certain lady walks into the room?","Dee","Randy, I've noticed that too","Marty","That's a signal problem, on the transmitter, I'll look into it","Dee","He's looking into it now, everybody, he's staring right at it - he hasn't touched a thing"}},
{"r5_obit_caller_oakes_bus_horn","obituary",15,150,8,21,1,{"Caller - Kim","I'd like to say Mr. Wilbur Oakes, he drove school bus fourteen in Rosewood for thirty years","Caller - Kim","He knew every kid's birthday, on your birthday he'd honk the horn at your stop, once for every year","Caller - Kim","My boy turned nine in May - Mr. Oakes honked nine times, and half the street came out on their porches to holler at him","Caller - Kim","And he hollered right back, 'it's his birthday!' Like that settled it","Marty","Wilbur Oakes, of Rosewood - bus fourteen"}},
{"r8_hor_woman_at_six","caller_story_horror",15,200,21,4,2,{"Almon","There's a woman walks past our fence about six in the evening - dead as they come","June","One of them, walking past","Almon","Every evening, blue dress, one shoe - she comes up from the creek side and goes off toward the church","Almon","Never turns her head - not once, we got kids hollering in that yard, we got a generator running, and she don't turn her head","June","Have you had to do anything about her?","Almon","No, that's the part I can't explain to my brother - she's walking somewhere","Almon","They don't walk somewhere, they come at a noise, this one's got a place to be at six o'clock","Almon","My wife set a chair by the window for it - I ain't talked her out of that yet"}},
{"r8_hor_calling_cows","caller_story_horror",15,190,1,5,1,{"Dee","Dee here, you're on ninety-nine six, go ahead","Otho","Somebody's calling cows in on the Kelso place, evening and morning both","Dee","Calling them how?","Otho","The way you do, hollering, you know - every farm's got their own holler and that one's the Kelsos'","Dee","Are there cattle up there?","Otho","There ain't been a cow on that place since Lurlene sold out in ninety-one - sale barn took every head","Otho","And Lurlene Kelso's in Louisville, or she was, and she's eighty years old and it ain't her voice anyhow","Dee","Somebody living up there with their own stock, maybe","Otho","Then they're calling 'em twice a day and nothing's coming - that's the sound of it, it's calling and calling and nothing comes"}},
{"r8_hor_called_me_hon","caller_story_horror",15,190,0,4,1,{"Darlene","I know how this is going to land, a woman called me hon","June","Half the county calls me hon","Darlene","That's what I mean - it's nothing, it's a nothing word","Darlene","She said it the way my mother said it, two beats, with the little drop on it - hon-ny, almost","June","Somebody from the same place, maybe","Darlene","My mother was from Ekron and she was the only one I ever heard say it like that in my life - forty-one years","Darlene","And she's been gone since March, before any of this - she had the cancer and she went in March","June","I'm sorry","Darlene","I sat down in the road, right down in the gravel, in front of a stranger - she helped me up and I let her and I'd like that back"}},
{"r8_hor_never_looked_at_fire","caller_story_horror",15,185,23,5,1,{"Ewell","A fella come in on us at the camp, said he was a hunter, canvas coat and all, in July","June","Go ahead","Ewell","Never set the rifle down, kept it in his hands the whole time, which, fine - I'd want mine too, and I don't judge a man for that","Ewell","He never looked at the fire","June","Not once?","Ewell","Three hours, you cannot sit at a fire and not look at it - try it sometime, your eyes go to it, it's a fire","Ewell","He looked at every one of us, slow, round the circle, then went round again","June","Did he eat?","Ewell","Took a plate and set it beside him, we buried that plate of food in the morning - I don't know why we didn't just wash it"}},
}
